      const entry = createContextEntry(0, pivots, 0);

      storage.setPayload(entry);
      expect(storage.hasPayload(0)).toBe(true);

      storage.deletePayload(0);
      expect(storage.hasPayload(0)).toBe(false);
    });
  });

