      telemetry.recordReading();

      const entry = createContextEntry(0, new Map(), 0);
      storage.setPayload(entry);

      telemetry.recordReading();

      const report = telemetry.getReport();
      expect(validateI6aMemoryConstraint(report)).toBe(true);
